	URL        string            // e.g., "https://127.0.0.1:PORT"
	CACertFile string            // PEM file path for GIT_SSL_CAINFO
	BareDirs   map[string]string // repo path (e.g., "testorg/main-repo") -> bare dir on filesystem
}

