	createCheckpointOrphanRoot(t, ctx, env.remoteDir, env.defaultBranch, "R1")
	appendCheckpointCommit(t, ctx, env.remoteDir, env.defaultBranch, "r2.json", `{"step":2}`)
	r3Hash := appendCheckpointCommit(t, ctx, env.remoteDir, env.defaultBranch, "r3.json", `{"step":3}`)

	// Local repo: do a shallow fetch of just the metadata branch tip.
	// This gives local the R3 commit but cuts ancestry at the shallow boundary.
	shallowFetchArgs := []string{
		"fetch", "--no-tags", "--depth=1",
		env.remoteDir,
		"+refs/heads/" + paths.MetadataBranchName + ":refs/heads/" + paths.MetadataBranchName,
	}
	runGit(t, ctx, env.localDir, shallowFetchArgs...)
	require.Equal(t, r3Hash, getRefHash(t, ctx, env.localDir, paths.MetadataBranchName))

	// Local: append a commit on top of R3. This is the unpushed local work.
	lHash := appendCheckpointCommit(t, ctx, env.localDir, env.defaultBranch, "l.json", `{"side":"local"}`)
	require.NotEqual(t, r3Hash, lHash)

	// Remote: advance its own metadata branch with a separate orphan-style
	// rewrite so the new remote tip is unreachable from L through R3. (Force
	// the remote to a brand-new orphan chain.)
	runGit(t, ctx, env.remoteDir, "update-ref", "-d", "refs/heads/"+paths.MetadataBranchName)
	createCheckpointOrphanRoot(t, ctx, env.remoteDir, env.defaultBranch, "R-prime")

