	require.Equal(t, r2Hash, getRefHash(t, ctx, env.localDir, paths.MetadataBranchName))

	appendCheckpointCommit(t, ctx, env.localDir, env.defaultBranch, "l.json", `{"side":"local"}`)

	runGit(t, ctx, env.remoteDir, "update-ref", "-d", "refs/heads/"+paths.MetadataBranchName)
	createCheckpointOrphanRoot(t, ctx, env.remoteDir, env.defaultBranch, "R-prime")

