		strings.Contains(msg, "unshallow ") ||
		strings.Contains(msg, "fetch --depth")
	assert.Truef(t, hasActionable,
		"shallow-boundary fetch error must include a user-actionable hint (entire doctor / git fetch --unshallow); got: %s", msg)
}

