func repoCurrentBranch(t *testing.T, ctx context.Context, repoDir string) string {
	t.Helper()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--abbrev-ref", "HEAD")
	cmd.Dir = repoDir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.Output()
	require.NoError(t, err)
	return strings.TrimSpace(string(out))
}

// createCheckpointOrphanRoot creates a fresh entire/checkpoints/v1 orphan
// branch in repoDir with a single root commit containing a metadata.json file.
// Returns the commit hash. Leaves HEAD on the default branch.
func createCheckpointOrphanRoot(t *testing.T, ctx context.Context, repoDir, defaultBranch, label string) string {
	t.Helper()

	runGit(t, ctx, repoDir, "checkout", "--orphan", paths.MetadataBranchName)
	runGit(t, ctx, repoDir, "rm", "-rf", ".")

	contents := fmt.Sprintf(`{"checkpoint": %q}`, label)
	testutil.WriteFile(t, repoDir, "metadata.json", contents)
	testutil.GitAdd(t, repoDir, "metadata.json")
	runGit(t, ctx, repoDir, "-c", "commit.gpgsign=false", "commit", "-m", "checkpoint "+label)

	hash := getRefHash(t, ctx, repoDir, paths.MetadataBranchName)
	runGit(t, ctx, repoDir, "checkout", defaultBranch)
	return hash
}

// appendCheckpointCommit adds a checkpoint commit on top of the current
// metadata-branch tip in repoDir. fileName/contents distinguish commits in
// assertions. Returns the new commit hash. HEAD is restored to defaultBranch.
func appendCheckpointCommit(t *testing.T, ctx context.Context, repoDir, defaultBranch, fileName, contents string) string {
	t.Helper()

	runGit(t, ctx, repoDir, "checkout", paths.MetadataBranchName)
	testutil.WriteFile(t, repoDir, fileName, contents)
	testutil.GitAdd(t, repoDir, fileName)
	runGit(t, ctx, repoDir, "-c", "commit.gpgsign=false", "commit", "-m", "checkpoint "+fileName)

	hash := getRefHash(t, ctx, repoDir, paths.MetadataBranchName)
	runGit(t, ctx, repoDir, "checkout", defaultBranch)
	return hash
}

// createOrphanRootWithEmptyTree creates an empty-tree root commit on the
// metadata branch in repoDir -- reproduces the historical "orphan-bug" commit
// shape that filtering logic must skip during replay. Returns the commit
// hash. Leaves HEAD on defaultBranch.
func createOrphanRootWithEmptyTree(t *testing.T, ctx context.Context, repoDir, defaultBranch string) string {
	t.Helper()

	runGit(t, ctx, repoDir, "checkout", "--orphan", paths.MetadataBranchName)
	runGit(t, ctx, repoDir, "rm", "-rf", ".")
	runGit(t, ctx, repoDir, "-c", "commit.gpgsign=false", "commit", "--allow-empty", "-m", "empty orphan root")

	hash := getRefHash(t, ctx, repoDir, paths.MetadataBranchName)
	runGit(t, ctx, repoDir, "checkout", defaultBranch)
	return hash
}

func runGit(t *testing.T, ctx context.Context, dir string, args ...string) {
	t.Helper()
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.CombinedOutput()
	require.NoErrorf(t, err, "git %s failed: %s", strings.Join(args, " "), out)
}

func getRefHash(t *testing.T, ctx context.Context, repoDir, refName string) string {
	t.Helper()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", refName)
	cmd.Dir = repoDir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.Output()
	require.NoErrorf(t, err, "git rev-parse %s failed in %s", refName, repoDir)
	return strings.TrimSpace(string(out))
}

// reachableHashes returns every commit reachable from the given ref in repoDir,
// using `git rev-list`. Order is newest-first, matching git's default.
func reachableHashes(t *testing.T, ctx context.Context, repoDir, ref string) []string {
	t.Helper()
	cmd := exec.CommandContext(ctx, "git", "rev-list", ref)
	cmd.Dir = repoDir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.Output()
	require.NoErrorf(t, err, "git rev-list %s failed in %s", ref, repoDir)
	hashes := strings.Split(strings.TrimSpace(string(out)), "\n")
	if len(hashes) == 1 && hashes[0] == "" {
		return nil
	}
	return hashes
}

// readBlobAtRef returns the contents of path at the given ref, or "" if absent.
func readBlobAtRef(t *testing.T, ctx context.Context, repoDir, ref, path string) string {
	t.Helper()
	cmd := exec.CommandContext(ctx, "git", "show", ref+":"+path)
	cmd.Dir = repoDir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.Output()
	if err != nil {
		return ""
	}
	return string(out)
}

